import {
  KeyboardEvent as ReactKeyboardEvent,
  ReactNode,
  RefCallback,
  useCallback,
  useEffect,
  useRef,
  useState,
} from 'react';
import { createPortal } from 'react-dom';

import { PopoverContainer } from './Popover.styles';

export interface PopoverRenderProps {
  close: () => void;
}

export interface PopoverTriggerRenderProps extends PopoverRenderProps {
  triggerRef: RefCallback<HTMLElement>;
  isOpen: boolean;
  open: () => void;
  onTriggerKeyDown: (event: ReactKeyboardEvent<HTMLElement>) => void;
}

export interface PopoverProps {
  dataTestId?: string;
  onOpen?: () => void;
  renderTrigger: (props: PopoverTriggerRenderProps) => ReactNode;
  children: (props: PopoverRenderProps) => ReactNode;
}

const POPOVER_OFFSET = 8;
const VIEWPORT_PADDING = 8;

export const Popover = ({
  dataTestId,
  onOpen,
  renderTrigger,
  children,
}: PopoverProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const [position, setPosition] = useState({ top: 0, left: 0 });
  const triggerRef = useRef<HTMLElement | null>(null);
  const popoverRef = useRef<HTMLDivElement>(null);

  const setTriggerRef = useCallback<RefCallback<HTMLElement>>((element) => {
    triggerRef.current = element;
  }, []);

  const updatePosition = useCallback(() => {
    const trigger = triggerRef.current;

    if (!trigger) return;

    const triggerRect = trigger.getBoundingClientRect();
    const popoverWidth = popoverRef.current?.getBoundingClientRect().width ?? 0;
    const maxLeft = Math.max(
      VIEWPORT_PADDING,
      window.innerWidth - popoverWidth - VIEWPORT_PADDING,
    );
    const left = Math.max(
      VIEWPORT_PADDING,
      Math.min(triggerRect.left, maxLeft),
    );

    setPosition({
      top: triggerRect.bottom + POPOVER_OFFSET,
      left,
    });
  }, []);

  const close = useCallback(() => {
    setIsOpen(false);
  }, []);

  const open = useCallback(() => {
    onOpen?.();
    updatePosition();
    setIsOpen(true);
  }, [onOpen, updatePosition]);

  const handleTriggerKeyDown = useCallback(
    (event: ReactKeyboardEvent<HTMLElement>) => {
      if (event.key !== 'Enter' && event.key !== ' ') return;

      event.preventDefault();
      open();
    },
    [open],
  );

  useEffect(() => {
    if (!isOpen) return undefined;

    const handleMouseDown = (event: globalThis.MouseEvent) => {
      const target = event.target as Node;

      if (
        triggerRef.current?.contains(target) ||
        popoverRef.current?.contains(target)
      ) {
        return;
      }

      close();
    };
    const handleKeyDown = (event: globalThis.KeyboardEvent) => {
      if (event.key === 'Escape') {
        close();
      }
    };

    updatePosition();
    document.addEventListener('mousedown', handleMouseDown);
    document.addEventListener('keydown', handleKeyDown);
    window.addEventListener('resize', updatePosition);
    window.addEventListener('scroll', updatePosition, true);

    return () => {
      document.removeEventListener('mousedown', handleMouseDown);
      document.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('resize', updatePosition);
      window.removeEventListener('scroll', updatePosition, true);
    };
  }, [close, isOpen, updatePosition]);

  return (
    <>
      {renderTrigger({
        triggerRef: setTriggerRef,
        isOpen,
        open,
        close,
        onTriggerKeyDown: handleTriggerKeyDown,
      })}

      {isOpen &&
        createPortal(
          <PopoverContainer
            data-testid={dataTestId}
            ref={popoverRef}
            style={position}
          >
            {children({ close })}
          </PopoverContainer>,
          document.body,
        )}
    </>
  );
};
